import{_ as r,c as i,o as a,a2 as o}from"./chunks/framework.mqLGQ42V.js";const m=JSON.parse('{"title":"原点与冻结 (Origin / Freeze) - Rive 编辑器","description":"原点 (Origin) 是对象在舞台上进行变换（如旋转或缩放）的基础点。 你可以将原点视为对象变换的中心。当你旋转一个对象时，它会绕着原点旋转；当你缩放一个对象时，它会向着或背离原点进行缩放。","frontmatter":{"title":"原点与冻结 (Origin / Freeze) - Rive 编辑器","description":"原点 (Origin) 是对象在舞台上进行变换（如旋转或缩放）的基础点。 你可以将原点视为对象变换的中心。当你旋转一个对象时，它会绕着原点旋转；当你缩放一个对象时，它会向着或背离原点进行缩放。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 基础概念, 原点与冻结"}]]},"headers":[],"relativePath":"editor/fundamentals/origin-freeze.md","filePath":"editor/fundamentals/origin-freeze.md","lastUpdated":1774867914000}'),t={name:"editor/fundamentals/origin-freeze.md"};function n(d,e,s,l,p,c){return a(),i("div",null,[...e[0]||(e[0]=[o('<p>基础概念</p><h1 id="原点与冻结-origin-freeze" tabindex="-1">原点与冻结 (Origin / Freeze) <a class="header-anchor" href="#原点与冻结-origin-freeze" aria-label="Permalink to &quot;原点与冻结 (Origin / Freeze)&quot;">​</a></h1><p>原点 (Origin) 是对象在舞台上进行变换（如旋转或缩放）的基础点。</p><h2 id="​-原点-origin" tabindex="-1"><a href="#origin">​</a> 原点 (Origin) <a class="header-anchor" href="#​-原点-origin" aria-label="Permalink to &quot;[​](#origin) 原点 (Origin)&quot;">​</a></h2><p>你可以将原点视为对象变换的中心。当你旋转一个对象时，它会绕着原点旋转；当你缩放一个对象时，它会向着或背离原点进行缩放。</p><p>默认情况下，大多数对象的原点都位于其几何中心。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 原点示例 Pn)</p></blockquote><h2 id="​-冻结-freeze" tabindex="-1"><a href="#freeze">​</a> 冻结 (Freeze) <a class="header-anchor" href="#​-冻结-freeze" aria-label="Permalink to &quot;[​](#freeze) 冻结 (Freeze)&quot;">​</a></h2><p>冻结功能允许你在不影响对象当前视觉位置的情况下，重新定位其原点。这在绑定骨骼或调整复杂形状的旋转中心时非常有用。</p><p>在 Rive 编辑器中，你可以通过按下快捷键 <code>Y</code> 来启用冻结模式，然后自由拖动原点。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 冻结示例 Pn)</p></blockquote><p><a href="/docs/editor/fundamentals/importing-assets">导入资源 (Importing Assets)</a><a href="/docs/editor/fundamentals/pen-tool-overview">钢笔工具概览 (Pen Tool Overview)</a></p>',12)])])}const g=r(t,[["render",n]]);export{m as __pageData,g as default};
